import argparse
import hashlib
import json
from pathlib import Path
import time
import numpy as np
from scipy.optimize import least_squares
# Search domain for the toaster rectangle fit. Heights come from the self-play constants.
CONFIG = {'initial_height_m': sp.TOASTER_SLOT_HEIGHT_M, 'minimum_height_m': sp.TOASTER_RIM_HEIGHT_BOUNDS_M[0], 'maximum_height_m': sp.TOASTER_RIM_HEIGHT_BOUNDS_M[1], 'length_bounds_m': [0.03, 0.3], 'width_bounds_m': [0.003, 0.2], 'robust_pixel_scale': 2.0, 'jitter_sigma_pixels': 1.0, 'jitter_repetitions': 100, 'random_seed': 7}

def rectangle(center, yaw, length, width):
    u = np.array([np.cos(yaw), np.sin(yaw), 0.0])
    v = np.array([-np.sin(yaw), np.cos(yaw), 0.0])
    return np.array(center) + np.array([-1, -1, 1, 1])[:, None] * length / 2 * u + np.array([-1, 1, 1, -1])[:, None] * width / 2 * v

def project(view, points):
    r, c, _ = view.project(points)
    return np.column_stack([c, r])

def on_plane(view, pixels, height):
    pixels = np.asarray(pixels)
    rays = view.rays(pixels[:, 1], pixels[:, 0])
    return view.pos + rays * ((height - view.pos[2]) / rays[:, 2])[:, None]

def initial_geometry(annotations, views):
    result = {name: on_plane(views['cam_head'], values['cam_head'], CONFIG['initial_height_m']) for name, values in annotations['rectangles'].items()}
    if annotations.get('divider_edges'):
        outer = result['outer']
        center = outer.mean(axis=0)
        u = (outer[2] + outer[3] - outer[0] - outer[1]) / 2
        length = np.linalg.norm(u)
        u /= length
        v = np.array([-u[1], u[0], 0.0])
        edges = annotations['divider_edges']['cam_head']
        left, right = [float(np.mean(on_plane(views['cam_head'], edges[edge], CONFIG['initial_height_m']) @ v)) for edge in ('left', 'right')]
        center += ((left + right) / 2 - center @ v) * v
        result['divider'] = rectangle(center, np.arctan2(u[1], u[0]), length, right - left)
    return result

def fit(annotations, views, initial=None):
    names = list(annotations['rectangles'])
    observed = annotations['rectangles']
    start = initial_geometry(annotations, views)
    axes = [(p[2] + p[3] - (p[0] + p[1])) / 2 for p in start.values()]
    yaw = np.arctan2(np.mean(axes, axis=0)[1], np.mean(axes, axis=0)[0])
    coplanar = annotations['coplanar']
    p0 = [yaw]
    low = [-2 * np.pi]
    high = [2 * np.pi]
    if coplanar:
        p0 += [CONFIG['initial_height_m']]
        low += [CONFIG['minimum_height_m']]
        high += [CONFIG['maximum_height_m']]
    for name in names:
        p = start[name]
        center = p.mean(axis=0)
        length = np.linalg.norm((p[2] + p[3] - p[0] - p[1]) / 2)
        width = np.linalg.norm((p[1] + p[2] - p[0] - p[3]) / 2)
        p0 += [*center[:2]]
        low += [-0.6, -0.6]
        high += [0.6, 0.6]
        if not coplanar:
            p0 += [center[2]]
            low += [CONFIG['minimum_height_m']]
            high += [CONFIG['maximum_height_m']]
        p0 += [length, width]
        low += [CONFIG['length_bounds_m'][0], CONFIG['width_bounds_m'][0]]
        high += [CONFIG['length_bounds_m'][1], CONFIG['width_bounds_m'][1]]
    strip = annotations.get('divider_edges')
    if strip:
        assert names == ['outer']
        p0 += [0.0, CONFIG['initial_height_m'] - 0.01, sp.TOASTER_DIVIDER_INITIAL_WIDTH_M]
        low += [sp.TOASTER_DIVIDER_OFFSET_BOUNDS_M[0], 0.79, sp.TOASTER_DIVIDER_WIDTH_BOUNDS_M[0]]  # Preserve the separate below-lip divider height range.
        high += [sp.TOASTER_DIVIDER_OFFSET_BOUNDS_M[1], 1.12, sp.TOASTER_DIVIDER_WIDTH_BOUNDS_M[1]]

    def unpack(p):
        result = {}
        offset = 2 if coplanar else 1
        for name in names:
            x, y = p[offset:offset + 2]
            offset += 2
            z = p[1] if coplanar else p[offset]
            if not coplanar:
                offset += 1
            length, width = p[offset:offset + 2]
            offset += 2
            result[name] = rectangle([x, y, z], p[0], length, width)
        if strip:
            outer = result['outer']
            offset, z, width = p[-3:]
            v = np.array([-np.sin(p[0]), np.cos(p[0]), 0.0])
            center = outer.mean(axis=0) + offset * v
            center[2] = z
            result['divider'] = rectangle(center, p[0], np.linalg.norm(outer[2] - outer[1]), width)
        return result

    def residual(p, camera_only=None):
        rects = unpack(p)
        errors = []
        for name in names:
            for camera, pixels in observed[name].items():
                if camera_only and camera != camera_only:
                    continue
                pixels = np.asarray(pixels, float)
                good = np.isfinite(pixels).all(axis=1)
                errors.extend((project(views[camera], rects[name])[good] - pixels[good]).ravel())
        if strip:
            for camera, edges in strip.items():
                if camera_only and camera != camera_only:
                    continue
                projected = project(views[camera], rects['divider'])
                for edge, indices in [('left', [0, 3]), ('right', [1, 2])]:
                    a, b = projected[indices]
                    direction = b - a
                    normal = np.array([-direction[1], direction[0]]) / np.linalg.norm(direction)
                    errors.extend((np.asarray(edges[edge]) - a) @ normal)
        return np.asarray(errors)
    p0 = np.clip(p0 if initial is None else initial, np.array(low) + 1e-08, np.array(high) - 1e-08)
    result = least_squares(residual, p0, bounds=(low, high), loss='soft_l1', f_scale=CONFIG['robust_pixel_scale'], max_nfev=500, xtol=1e-11, ftol=1e-11, gtol=1e-11)
    rects = unpack(result.x)
    return {'corners': {k: v.tolist() for k, v in rects.items()}, 'parameters': result.x.tolist(), 'success': bool(result.success), 'reprojection_rms_px': float(np.sqrt(np.mean(residual(result.x) ** 2))), 'reprojection_per_view': {camera: float(np.sqrt(np.mean(residual(result.x, camera) ** 2))) for camera in views if any((camera in observed[n] for n in names))}, 'divider_endpoints_inferred_from_outer_length': bool(strip), 'jacobian_rank': int(np.linalg.matrix_rank(result.jac)), 'parameter_count': len(result.x), 'evaluations': result.nfev}
